<?php
namespace App\Http\Controllers; use App\Models\ProductSku; use Illuminate\Http\Request;
class CartController extends Controller {private function cart(Request $r){return $r->session()->get('cart',[]);}public function index(Request $r){$cart=$this->cart($r);$items=ProductSku::with('product')->whereIn('sku_id',array_keys($cart))->get()->keyBy('sku_id');$subtotal=0;foreach($cart as $id=>$qty){if(isset($items[$id]))$subtotal += $items[$id]->price*$qty;}return view('store.cart',compact('cart','items','subtotal'));}public function add(Request $r,ProductSku $sku){$qty=max(1,$r->integer('quantity',1));$cart=$this->cart($r);$new=($cart[$sku->sku_id]??0)+$qty;if($new>$sku->stock_quantity)return back()->with('error','Requested quantity is not available.');$cart[$sku->sku_id]=$new;$r->session()->put('cart',$cart);return back()->with('success','Product added to cart.');}public function update(Request $r){$data=$r->validate(['quantities'=>'array','quantities.*'=>'integer|min:0']);$cart=$this->cart($r);foreach($data['quantities']??[] as $id=>$qty){$sku=ProductSku::find($id);if(!$sku){unset($cart[$id]);continue;}if($qty>$sku->stock_quantity)return back()->with('error',"Quantity for {$sku->sku_code} exceeds stock.");if($qty===0)unset($cart[$id]);else$cart[$id]=$qty;}$r->session()->put('cart',$cart);return back()->with('success','Cart updated.');}public function remove(Request $r,ProductSku $sku){$cart=$this->cart($r);unset($cart[$sku->sku_id]);$r->session()->put('cart',$cart);return back()->with('success','Item removed.');}}
